import hashlib, json
ROLES = {"doctor": {"read_checkup"}, "hr": {"read_summary"}}
log = []

def digest(prev, entry):
    body = json.dumps(entry, sort_keys=True, ensure_ascii=False)
    return hashlib.sha256((prev + body).encode()).hexdigest()[:8]

def access(user, tenant, action, target_tenant, emp):
    ok = tenant == target_tenant and action in ROLES[user["role"]]
    entry = {"who": user["id"], "tenant": tenant, "what": action, "emp": emp, "ok": ok}
    entry["hash"] = digest(log[-1]["hash"] if log else "0" * 8, entry)
    log.append(entry)
    return ok

def verify():
    prev = "0" * 8
    for e in log:
        rest = {k: v for k, v in e.items() if k != "hash"}
        if digest(prev, rest) != e["hash"]:
            return False
        prev = e["hash"]
    return True

doc = {"id": "u1", "role": "doctor"}
hr = {"id": "u2", "role": "hr"}
print(access(doc, "A", "read_checkup", "A", "e17"))
print(access(hr, "A", "read_checkup", "A", "e17"))   # 역할 밖
print(access(doc, "A", "read_checkup", "B", "e03"))  # 다른 회사(테넌트)
print("변조 없음", verify())
log[1]["ok"] = True   # 누가 거절 기록을 고치면
print("변조 없음", verify())

