BLOCK = [r"\.env\b", r"prod", r"DROP\s+TABLE", r"git\s+push"]

def check(payload):
    cmd = payload.get("tool_input", {}).get("command", "")
    for p in BLOCK:
        if re.search(p, cmd, re.I):
            return 2, f"막음: '{p}' 규칙 — {cmd}"
    return 0, f"통과: {cmd}"

if __name__ == "__main__":
    for c in ["pytest -q", "cat .env", "psql $PROD_URL -c 'DROP TABLE checkup'", "git push origin main"]:
        code, msg = check({"tool_name": "Bash", "tool_input": {"command": c}})
        print(code, msg)
